import csv


def parse_people(text):
    result = []
    for row in csv.reader(text.splitlines()):
        if not row or not any(field.strip() for field in row):
            continue
        if row[0] == 'name':
            continue
        name, age, active = row
        result.append({'name': name, 'age': int(age), 'active': active == 'yes'})
    return result
